// Compute yesterday ISO date (NL tz), used as range anchor
const now = new Date();
const y = new Date(now.getTime() - 24*60*60*1000);
const iso = y.toISOString().split('T')[0];
return [{ json: { targetDate: iso, todayIso: now.toISOString().split('T')[0] } }];

// Aggregate all engine data into one Daily KPI record
const targetDate = $('Prep Date').item.json.targetDate;

const adVariants = $('Read Ad Variants').all().map(i => i.json);
const conv       = $('Read Conversion Tracking').all().map(i => i.json);
const customers  = $('Read Customer Segments').all().map(i => i.json);
const b2b        = $('Read B2B Leads').all().map(i => i.json);
const email      = $('Read Email Performance').all().map(i => i.json);

// --- Ad spend + ad-driven revenue ---
let adSpend = 0, winnerCount = 0, activeCampaigns = new Set();
for (const v of adVariants) {
  adSpend += Number(v.Spend || 0);
  if (v['Winner Status'] === 'Winner') winnerCount++;
  if (v.Status === 'Active' && Array.isArray(v.Campaign)) v.Campaign.forEach(c => activeCampaigns.add(c));
}

// --- Conversion + revenue by channel ---
let shopRev = 0, bolRev = 0, b2bRev = 0, sessions = 0, orders = 0;
for (const c of conv) {
  shopRev += Number(c['Shopify Revenue'] || 0);
  bolRev  += Number(c['Bol Revenue']     || 0);
  b2bRev  += Number(c['B2B Revenue']     || 0);
  sessions += Number(c['Sessions'] || 0);
  orders   += Number(c['Orders']   || 0);
}
const totalRev = shopRev + bolRev + b2bRev;
const shopCR = sessions > 0 ? (orders / sessions) * 100 : null;

// --- Customers ---
let newC = 0, repC = 0;
for (const k of customers) {
  if (k['Last Order Date'] === targetDate) {
    if ((Number(k['Order Count']) || 0) <= 1) newC++;
    else repC++;
  }
}
const repeatRate = (newC + repC) > 0 ? (repC / (newC + repC)) * 100 : 0;

// --- Email ---
let emailRev = 0;
for (const e of email) emailRev += Number(e['Attributed Revenue'] || 0);
const emailShare = totalRev > 0 ? (emailRev / totalRev) * 100 : 0;

// --- B2B pipeline value ---
let pipelineValue = 0;
for (const l of b2b) pipelineValue += (Number(l['Estimated Monthly Value']) || 0) * 12;
const newB2B = b2b.filter(l => l['Added Date'] === targetDate).length;

// --- Inventory status (simple: use hero product if available) ---
let invStatus = 'Healthy';
const heroDaily = orders > 0 ? orders : 10;
// placeholder: real implementation would pull Inventory table

const payload = {
  'Date': targetDate,
  'Total Revenue': totalRev,
  'Shopify Revenue': shopRev,
  'Bol Revenue': bolRev,
  'B2B Revenue': b2bRev,
  'Total Ad Spend': adSpend,
  'Shopify Conversion Rate': shopCR,
  'New Customers': newC,
  'Repeat Customers': repC,
  'Email Revenue': emailRev,
  'B2B Leads Added': newB2B,
  'B2B Pipeline Value': pipelineValue,
  'Inventory Status': invStatus,
  'Active Campaigns': activeCampaigns.size,
  'Winner Ads Count': winnerCount
};

// Summary variables for Telegram
const roas = adSpend > 0 ? totalRev / adSpend : null;
const cpa  = newC > 0 ? adSpend / newC : null;

return [{ json: { payload, targetDate, summary: { totalRev, roas, newC, repC, cpa, emailShare, pipelineValue, winnerCount } } }];

// Build 5-line Dutch Telegram summary
const s = $('Aggregate KPIs').item.json.summary;
const d = $('Aggregate KPIs').item.json.targetDate;
const fmtEur = n => '€' + Math.round(n || 0).toLocaleString('nl-NL');
const fmtNum = (n, d=2) => n == null ? '—' : Number(n).toFixed(d);

// Pick one hot insight
let insight = '';
if (s.winnerCount >= 3) insight = `${s.winnerCount} winner ads draaien — goed moment om budget te schalen`;
else if (s.roas && s.roas < 2) insight = `ROAS onder 2.0 — losers pauzeren, creative refresh overwegen`;
else if (s.emailShare < 15) insight = `Email share slechts ${fmtNum(s.emailShare,1)}% — flows kunnen veel meer opbrengen`;
else if (s.pipelineValue > 50000) insight = `B2B pipeline ${fmtEur(s.pipelineValue)} jaarwaarde — follow-ups prioriteren`;
else insight = `Omzetmix stabiel, geen rode vlaggen vandaag`;

// Pick one action
let action = '';
if (s.roas && s.roas < 1.5) action = 'Check /pattern-detector → welke ads zijn de boosdoeners?';
else if (s.newC === 0) action = 'Geen nieuwe klanten gisteren — acquisition funnel checken';
else if (s.cpa && s.cpa > 15) action = `CPA €${fmtNum(s.cpa,2)} — test goedkopere hook-angle`;
else action = 'Geen urgente actie nodig — blijf monitoren';

const msg = `🌱 *Bamboo Daily Brief* — ${d}\n\n` +
  `💰 Omzet: ${fmtEur(s.totalRev)}  ·  ROAS: ${fmtNum(s.roas)}\n` +
  `👥 Klanten: ${s.newC} nieuw, ${s.repC} repeat  ·  CPA: ${s.cpa ? fmtEur(s.cpa) : '—'}\n` +
  `🔥 Insight: ${insight}\n` +
  `🎯 Actie: ${action}`;

return [{ json: { text: msg } }];
